import pandas as pd
from datetime import timedelta


def run(inputs: dict) -> dict:
    events = inputs["app_events"].copy()

    if events.empty:
        return {
            "user_sessions": pd.DataFrame(
                columns=[
                    "user_id",
                    "session_num",
                    "session_start",
                    "session_end",
                    "event_count",
                    "heartbeat_count",
                ]
            )
        }

    events = events.copy()
    events["event_ts"] = pd.to_datetime(events["event_ts"])

    events = events.sort_values(by=["user_id", "event_ts", "event_id"], kind="mergesort")

    threshold = timedelta(minutes=30)

    result_rows = []

    for user_id, grp in events.groupby("user_id", sort=False):
        grp = grp.sort_values(by=["event_ts", "event_id"], kind="mergesort")

        open_session = None  # dict: session_start, last_activity, event_count, heartbeat_count
        session_num = 0

        def finalize(session):
            result_rows.append(
                {
                    "user_id": user_id,
                    "session_num": session["session_num"],
                    "session_start": session["session_start"],
                    "session_end": session["last_activity"],
                    "event_count": session["event_count"],
                    "heartbeat_count": session["heartbeat_count"],
                }
            )

        for row in grp.itertuples(index=False):
            event_ts = row.event_ts
            event_type = row.event_type

            if event_type in ("view", "click", "logout"):
                needs_new_session = (
                    open_session is None
                    or (event_ts - open_session["last_activity"]) > threshold
                )

                if needs_new_session:
                    if open_session is not None:
                        finalize(open_session)
                    session_num += 1
                    open_session = {
                        "session_num": session_num,
                        "session_start": event_ts,
                        "last_activity": event_ts,
                        "event_count": 1,
                        "heartbeat_count": 0,
                    }
                else:
                    open_session["last_activity"] = event_ts
                    open_session["event_count"] += 1

                if event_type == "logout":
                    finalize(open_session)
                    open_session = None

            else:  # heartbeat
                if open_session is not None and (
                    event_ts - open_session["last_activity"]
                ) <= threshold:
                    open_session["event_count"] += 1
                    open_session["heartbeat_count"] += 1
                # else dropped

        if open_session is not None:
            finalize(open_session)

    result_df = pd.DataFrame(
        result_rows,
        columns=[
            "user_id",
            "session_num",
            "session_start",
            "session_end",
            "event_count",
            "heartbeat_count",
        ],
    )

    return {"user_sessions": result_df}
